    if(!bot.alive){bot.respawn-=dt;if(bot.respawn<=0){const s=bot.team==='red'?[[-5,-22],[5,-23],[-9,-17],[9,-19],[-5,2],[5,18],[9,22],[-8,24]][bots.filter(b=>b.team==='red').indexOf(bot)]:[[-7,20],[7,17],[-4,-3],[8,-10]][bots.filter(b=>b.team==='blue').indexOf(bot)];bot.root.position.set(s[0]+(Math.random()-.5)*2,0,s[1]+(Math.random()-.5)*2);bot.hp=100;bot.alive=true;bot.root.visible=true;}}
    else moveBot(bot,dt);
  }
}

function collidesPlayer(pos){
  const feet=pos.y-.92, head=pos.y-.08;
